124	    public function mount(?array $querystring, Request $request)
125	    {
126	        // Assign the querystring to current filters
127	        // From querystring property to Livewire property
128	        if ($querystring) {
129	            $querystring = unSerializeFilter($querystring);
130	            foreach ($querystring as $key => $value) {
131	                // If the key exists in the class, set the value
132	                if (property_exists($this, $key)) {
133	                    $key = 'f'.ucfirst($key);
134	                    $this->{$key} = $value;
135	                }
136	            }
137	
138	            // Check diameter filter values
139	            // If the $fDiameter is not empty, set the $fAllDiameter to 0
140	            if (count($this->fDiameter)) {
141	                $this->fAllDiameter = 0;
142	                // Force int values for diameter
143	                $this->fDiameter[0] = (int)$this->fDiameter[0];
144	                $this->fDiameter[1] = (int)$this->fDiameter[1];
145	
146	                if (
147	                    $this->fDiameter[0] == 0
148	                    || $this->fDiameter[1] == 0
149	                    || $this->fDiameter[0] > $this->fDiameter[1]
150	                ) {
151	                    // If the diameter is not valid, set it to empty array
152	                    $this->fDiameter = [];
153	                    $this->fAllDiameter = 1; // Set the all diameter filter to true
154	                }
155	            }
156	
157	            // if depth parameters are set, set the fAllDepthHeight to 0 (accordion open)
158	            if (count($this->depth)) {
159	                $this->fAllDepthHeight = 0;
160	            } else {
161	                $this->fAllDepthHeight = 1;
162	            }
163	
164	
165	        }
166	
167	        // Get products
168	        $this->getProductList();
169	        // Filters lists
170	        $this->defineFiltersLists();
171	
172	        // Define the diameter range
173	        if (!count($this->fDiameter)) {
174	            $this->fDiameter = [array_key_first($this->filterDiameter), array_key_last($this->filterDiameter)];
175	        }
176	        $this->diameterLabel = __('global.all'); // Default label for diameter, at the beginning is set to "All". This will be updated when the diameter filter is set, to numeric value or "All" again
177	
178	        $this->categories = Category::published()->navigationFilter()->orderBy('sort')->get();
179	    }
