208	    public function getProductList()
209	    {
210	        $innerProducts = ProdWrapper::published()->navigationFilter();
211	
212	        // Category
213	        if (count($this->fCategory)) {
214	            $innerProducts = $innerProducts->whereHas('category', function ($q) {
215	                $q->where(function ($q) {
216	                    foreach ($this->fCategory as $category => $value) {
217	                        if ($value === true) {
218	                            $q->orWhere('page_url->'.app()->getLocale(), $category);
219	                        }
220	                    }
221	                });
222	            });
223	            $this->resetSearch(); // Reset search if any filter is selected
224	        }
225	
226	
227	        // Application
228	        if (count($this->fApplication)) {
229	            $innerProducts = $innerProducts->whereHas('techData', function ($q) {
230	                $q->where(function ($q) {
231	                    foreach ($this->fApplication as $filter => $value) {
232	                        if ($value === true) {
233	                            $q->orWhere('id', $filter);
234	                        }
235	                    }
236	                });
237	            });
238	            $this->resetSearch(); // Reset search if any filter is selected
239	        }
240	
241	        // Diameter
242	        if (count($this->fDiameter) && $this->fAllDiameter === 0) {
243	            $innerProducts = $innerProducts->whereBetween('diameter', $this->fDiameter);
244	            $this->resetSearch(); // Reset search if any filter is selected
245	        }
246	
247	        // depth/height
248	        if (count($this->depth)) {
249	            $innerProducts = $innerProducts->whereBetween('depth_height', $this->depth);
250	            $this->resetSearch(); // Reset search if any filter is selected
251	        }
252	
253	        // lens range ("clear_value" field)
254	        if (count($this->lensRange)) {
255	            $innerProducts = $innerProducts->whereHas('lenses', function (Builder $q) {
256	
257	                // if first value is "0", do not consider min value for the query
258	                $q->when((int) $this->lensRange[0] == 0, function ($q) {
259	                    $q->where('clear_value', '<=', $this->lensRange[1]);
260	                }, function ($q) {
261	                    $q->whereBetween('clear_value', $this->lensRange);
262	                });
263	
264	            });
265	            $this->resetSearch(); // Reset search if any filter is selected
266	        }
267	
268	        // Lens tags (tag associati alle lenti, type_id 1)
269	        if (count($this->fLenstag)) {
270	            $innerProducts = $innerProducts->whereHas('lenses', function (Builder $q) {
271	                $q->whereHas('tags', function (Builder $q) {
272	                    $q->where(function (Builder $q) {
273	                        foreach ($this->fLenstag as $filter => $value) {
274	                            if ($value === true) {
275	                                $q->orWhere('prod_parts_tags.id', $filter);
276	                            }
277	                        }
278	                    });
279	                });
280	            });
281	            $this->resetSearch(); // Reset search if any filter is selected
282	        }
283	
284	        // IP
285	        if (count($this->fIp)) {
286	            $innerProducts = $innerProducts->whereHas('techData', function ($q) {
287	                $q->where(function ($q) {
288	                    foreach ($this->fIp as $filter => $value) {
289	                        if ($value === true) {
290	                            $q->orWhere('page_url->'.app()->getLocale(), $filter);
291	                        }
292	                    }
293	                });
294	            });
295	            $this->resetSearch(); // Reset search if any filter is selected
296	        }
297	
298	        // Lumen
299	        if (count($this->fLumen)) {
300	            $innerProducts = $innerProducts->whereHas('techData', function ($q) {
301	                $q->where(function ($q) {
302	                    foreach ($this->fLumen as $filter => $value) {
303	                        if ($value === true) {
304	                            $q->orWhere('page_url->'.app()->getLocale(), $filter);
305	                        }
306	                    }
307	                });
308	            });
309	            $this->resetSearch(); // Reset search if any filter is selected
310	        }
311	
312	        // Line
313	        if (count($this->fLine)) {
314	            $innerProducts = $innerProducts->where(function ($q) {
315	                foreach ($this->fLine as $filter => $value) {
316	                    if ($value === true) {
317	                        $q->orWhere('line_id', $filter);
318	                    }
319	                }
320	            });
321	            $this->resetSearch(); // Reset search if any filter is selected
322	        }
323	
324	        // Search
325	        if ($this->search) {
326	            if ($this->search_type === 'name') {
327	                // Search by special field, localized
328	                $innerProducts = $innerProducts->whereFullText('search_'.app()->getLocale(), $this->search);
329	
330	                // Search by ranking and relevance
331	                $this->products = $innerProducts->get();
332	                $pso = new ProductSearchOrder($this->products, $this->search);
333	                $this->products = $pso->getResult();
334	                // Order by relevance score
335	                $this->products = $this->products->sortByDesc('score')->values();
336	            }
337	            if ($this->search_type === 'code') {
338	                // Find products with Variants with code
339	                $innerProducts = $innerProducts->whereHas('variants', function ($query) {
340	                    $query->where('code', $this->search);
341	                });
342	
343	                $this->products = $innerProducts->orderBy('sort')->get();
344	            }
345	        } else {
346	            $this->products = $innerProducts->orderBy('sort')->get();
347	        }
348	
349	
350	        // Add the tech data to the products
351	        if (isset($this->products)) {
352	            $this->products->load(['techData' => fn ($q) => $q->published()]);
353	            // @phpstan-ignore argument.type
354	            $this->products->map(function (ProdWrapper&Model $product) {
355	                $product->setAttribute('techDataMounting', $product->techData->where('type', 'mounting')->first() ?? null);
356	                $product->setAttribute('techDataIP', $product->techData->where('type', 'ip')->first() ?? null);
357	                $product->setAttribute('techDataLumen', $product->techData->where('type', 'lumen')->first() ?? null);
358	                return $product;
359	            });
360	        } else {
361	            $this->products = new Collection();
362	        }
363	    }
