366	    /**
367	     * Updated
368	     *
369	     * @param string $property
370	     * @param string $value
371	     *
372	     * @return void
373	     */
374	    public function updated(string $property, ?string $value)
375	    {
376	        // From Livewire property to querystring property
377	        if (str_contains($property, '.')) {
378	            $hiddenFilter = explode('.', $property)[0];
379	            $urlFilter = strtolower($hiddenFilter);
380	            $urlFilter = ltrim($urlFilter, 'f');
381	
382	            // If the property is not in the authFiltersHidden, return
383	            if (!in_array($hiddenFilter, $this->authFiltersHidden)) {
384	                return;
385	            }
386	
387	            $this->{$urlFilter} = serializeFilter($this->{$hiddenFilter});
388	
389	            // Clear the filter
390	            $this->{$hiddenFilter} = clearFilter($this->{$hiddenFilter});
391	
392	        }
393	        // Update diameter
394	        if ($property === 'fAllDiameter' && (int)$value === 1) {
395	            // Reset the diameter filter on querystring
396	            $this->diameter = [];
397	        } else {
398	
399	        }
400	
401	        // Update product list with the new filters
402	        $this->getProductList();
403	        // Filters lists
404	        $this->defineFiltersLists();
405	    }
