412	    private function getCatID(): array
413	    {
414	        $toReturn = [];
415	        $allCat = [];
416	        foreach ($this->filterCategories as $category) {
417	            if (isset($this->fCategory[$category->page_url]) && $this->fCategory[$category->page_url] === true) {
418	                $toReturn[] = $category->id;
419	            }
420	            $allCat[] = $category->id;
421	        }
422	        // If no categories selected return all categories
423	        return count($toReturn) ? $toReturn : $allCat;
