428	     * Define Filters Lists
429	     *
430	     * @return void
431	     */
432	    private function defineFiltersLists(): void
433	    {
434	        // Get filters list to fill the filter list on the view
435	        $this->filterCategories = Category::published()->navigationFilter()->get();
436	        // Get current selected categories
437	        $this->selectedCategories = $this->getCatID();
438	
439	        // Get published active products
440	        $this->publishedActiveProducts = ProdWrapper::published()->whereIn('category_id', $this->selectedCategories)->pluck('id')->toArray();
441	
442	        // APPLICATION
443	        $this->filterApplication = ProdTechData::published()
444	            ->where('type', 'application')
445	            ->whereHas('products', function ($q) {
446	                $q->published()
447	                ->navigationFilter()
448	                ->whereIn('category_id', $this->selectedCategories);
449	            })
450	            ->orderBy('sort')
451	            ->get();
452	        // Clear not active filters
453	        foreach ($this->fApplication as $kFilterApplied => $value) {
454	            if (!$this->filterApplication->contains($kFilterApplied)) {
455	                $this->fApplication = [];
456	                $this->application = '';
457	            }
458	        }
459	
460	        // DIAMETER
461	        $this->filterDiameter = ProdWrapper::select('id', 'diameter')
462	            ->whereNotNull('diameter')
463	            ->get()
464	            ->pluck('diameter')
465	            ->toArray();
466	        sort($this->filterDiameter);
467	
468	
469	        // Lenti, elenco valori filtri
470	        // aggiungo valore 0 (v. updateLensRange per logica)
471	        $this->lensRangeValues =  ProdPart::published()
472	            ->where([
473	                ['type_id', 1]
474	            ])
475	            ->whereNotNull('clear_value')
476	            ->orderBy('clear_value')
477	            ->pluck('clear_value')
478	            ->toArray();
479	        sort($this->lensRangeValues);
480	
481	        // add "0" value at the beginning of the array, if not exists
482	        if (!in_array(0, $this->lensRangeValues)) {
483	            array_unshift($this->lensRangeValues, 0);
484	        }
485	
486	
487	        // LENS TAGS (tag associati alle lenti, type_id 1)
488	        $this->filterLensTags = ProdPartTag::byType(1)
489	            ->whereHas('parts')
490	            ->orderBy('id')
491	            ->get();
492	        // Clear not active filters
493	        foreach ($this->fLenstag as $kFilterApplied => $value) {
494	            if (!$this->filterLensTags->contains($kFilterApplied)) {
495	                $this->fLenstag = [];
496	                $this->lenstag = '';
497	            }
498	        }
499	
500	
501	        // IP
502	        $this->filterIps = ProdTechData::published()
503	            ->where('type', 'ip')
504	            ->whereHas('products', function ($q) {
505	                $q->published()
506	                ->navigationFilter()
507	                ->whereIn('category_id', $this->selectedCategories);
508	            })
509	            ->orderBy('sort')
510	            ->get();
511	        // Clear not active filters
512	        foreach ($this->fIp as $kFilterApplied => $value) {
513	            if (!$this->filterIps->firstWhere('page_url', $kFilterApplied)) {
514	                $this->fIp = [];
515	                $this->ip = '';
516	            }
517	        }
518	
519	        // LUMEN
520	        $this->filterLumen = ProdTechData::published()
521	            ->where('type', 'lumen')
522	            ->whereHas('products', function ($q) {
523	                $q->published()
524	                ->navigationFilter()
525	                ->whereIn('category_id', $this->selectedCategories);
526	            })
527	            ->orderBy('sort')
528	            ->get();
529	        // Clear not active filters
530	        foreach ($this->fLumen as $kFilterApplied => $value) {
531	            if (!$this->filterLumen->firstWhere('page_url', $kFilterApplied)) {
532	                $this->fLumen = [];
533	                $this->lumen = '';
534	            }
535	        }
536	
537	        $this->filterLine = ProdLine::orderBy('title')->get();
538	
539	        // Get the download type
540	        $this->downloadTypes = ProdDownloadType::cases();
541	
542	
543	        // DEPTH/HEIGHT
544	        $this->filterDepthHeightRange = ProdWrapper::published()
545	            ->whereIn('category_id', $this->selectedCategories)
546	            ->whereNotNull('depth_height')
547	            ->pluck('depth_height')
548	            ->toArray()
549	        ;
550	        ksort($this->filterDepthHeightRange);
551	
552	    }
