5	namespace App\Domain;
6	
7	use Illuminate\Database\Eloquent\Collection;
8	use Illuminate\Database\Eloquent\Model;
9	
10	class ProductSearchOrder
11	{
12	    private Collection $newResult;
13	    private Collection $result;
14	    private string $search;
15	
16	    /**
17	     * Method __construct
18	     *
19	     * @param Collection $result
20	     * @param string $search
21	     *
22	     * @return Collection
23	     */
24	    public function __construct(Collection $result, string $search)
25	    {
26	        $this->result = $result;
27	        $this->search = $search;
28	        $this->newResult = new Collection();
29	    }
30	
31	
32	    /**
33	     * Method getResult
34	     *
35	     * @return Collection
36	     */
37	    public function getResult(): Collection
38	    {
39	        // Assign a score to each product based on its relevance
40	        $this->newResult = $this->result->transform(function ($product) {
41	            $product->score = $this->calculateRelevanceScore($product, $this->search);
42	            return $product;
43	        });
44	
45	        // Sort the products by their relevance score in descending order
46	        return $this->newResult;
47	    }
48	
49	
50	    /**
51	     * Calculate the relevance score for a product.
52	     *
53	     * @param  mixed  $product
54	     * @return float
55	     */
56	    private function calculateRelevanceScore(Model $product, string $search): float
57	    {
58	        // Example scoring logic based on product attributes
59	        $score = 0.0;
60	
61	        // Increase score for each attribute that matches the search criteria
62	        if (mb_strtolower($product->title.'') === mb_strtolower($search)) {
63	            $score += 0.7; // Exact match on title
64	        }
65	        if (str_contains(mb_strtolower($product->title.''), mb_strtolower($search.''))) {
66	            $score += 0.6; // Contains string on title
67	        }
68	        if (str_contains(mb_strtolower($product->keywords.''), mb_strtolower($search.''))) {
69	            $score += 0.5; // Contains keywords
70	        }
71	
72	        /* Score by the number of matching words
73	        ------------------------------------------------------------------------------------------ */
74	        // Normalize the search string for comparison
75	        $terms = mb_strtolower(trim($search));
76	        $terms = preg_replace('/\s+/u', ' ', $terms) ?? '';
77	
78	        // Split the search string into single words
79	        $terms = explode(' ', $terms);
80	        $matchedTerms = 0;
81	
82	        if (count($terms) > 1) {
83	            foreach ($terms as $word) {
84	                if (str_contains(mb_strtolower($product->title.''), $word)) {
85	                    $matchedTerms++;
86	                    $score += 0.1; // Each matching word in title
87	                }
88	                if (str_contains(mb_strtolower($product->keywords.''), $word)) {
89	                    $score += 0.05; // Each matching word in keywords
90	                }
91	            }
92	
93	            // All words matched bonus
94	            if ($matchedTerms === count($terms)) {
95	                $score += 0.2; // Bonus for all words matched
96	
97	                // Extra bonus for exact match of the search string inside the title, example - search: "Eclissi mini 180" and title: "Eclissi mini 180 IP67"
98	                if (str_contains(mb_strtolower($product->title.''), mb_strtolower($this->search))) {
99	                    $score += 0.1;
100	                }
101	            }
102	        }
103	
104	
105	        return $score;
106	    }
107	}
